function signedRank(xs, mu){ var diffs=xs.map(function(x){return x-mu;});
  var nz=[]; for(var i=0;i<diffs.length;i++) if(diffs[i]!==0) nz.push(diffs[i]);
  var abs=nz.map(Math.abs);
  var idx=abs.map(function(v,i){return {v:v,i:i};}).sort(function(a,b){return a.v-b.v;});
  var ranks=new Array(abs.length);
  var i=0;
  while(i<idx.length){ var j=i; while(j+1<idx.length && idx[j+1].v===idx[i].v) j++; var avg=(i+j+2)/2; for(var k=i;k<=j;k++) ranks[idx[k].i]=avg; i=j+1; }
  var Wp=0,Wm=0;
  for(var k=0;k<nz.length;k++){ if(nz[k]>0) Wp+=ranks[k]; else Wm+=ranks[k]; }
  return {Wplus:Wp, Wminus:Wm, W:Math.min(Wp,Wm), n:nz.length};
}
var EXPORTS={signedRank:signedRank};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WilcoxonForgePure = EXPORTS; }
